import"./app.min.js";import"./popup.min.js";import"./cataloge.min.js";function clampQuantity(e){const t=parseFloat(e);return Number.isFinite(t)&&t>0?Math.max(1,t):1}function requestBasketAction(e,t){return BX?.ajax?.runComponentAction?BX.ajax.runComponentAction("brakes:basket.actions",e,{mode:"class",data:t}):Promise.reject(new Error("BX ajax unavailable"))}function updateItemQuantity(e,t){return requestBasketAction("update",{basketItemId:e,quantity:t})}function removeItem(e){return requestBasketAction("remove",{basketItemId:e})}document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".basket__products");if(!e)return;e.addEventListener("click",function(t){const a=t.target.closest(".basket__delete");if(a){const t=parseInt(a.dataset.basketItemId||"0",10)||0;t>0&&removeItem(t).then(()=>{window.location.reload()}).catch(()=>{});return}const n=t.target.closest("[data-basket-qty-step]");if(!n)return;const o=n.closest("[data-basket-item-id]");if(!o)return;const r=o.querySelector("[data-basket-qty]");if(!r)return;const c=parseFloat(n.dataset.basketQtyStep||"0")||0,l=clampQuantity(parseFloat(r.value||"1")+c);r.value=l;const s=parseInt(o.dataset.basketItemId||"0",10)||0;s>0&&updateItemQuantity(s,l).then(()=>{window.location.reload()}).catch(()=>{})}),e.addEventListener("change",function(t){const a=t.target.closest("[data-basket-qty]");if(!a)return;const n=a.closest("[data-basket-item-id]");if(!n)return;const o=clampQuantity(a.value);a.value=o;const r=parseInt(n.dataset.basketItemId||"0",10)||0;r>0&&updateItemQuantity(r,o).then(()=>{window.location.reload()}).catch(()=>{})})});
